from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from push_notifications.models import GCMDevice

class GCMDeviceTokenUpdateView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def put(self, request, device_id):
        new_reg_id = request.data.get("registration_id")
        # Enforce that device belongs to the authenticated user
        device = GCMDevice.objects.filter(
            id=device_id,
            user=request.user
        ).first()
        if not device:
            return Response({"error": "Device not found or access denied"}, status=status.HTTP_404_NOT_FOUND)

        device.registration_id = new_reg_id
        device.save(update_fields=["registration_id"])
        return Response({"status": "Push token updated"}, status=status.HTTP_200_OK)
